function knowledge_adoption_tables_ready():bool{if(data_is_demo())return true;$pdo=production_database_connection();if(!$pdo)return false;try{$tables=knowledge_adoption_tables();$s=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('.implode(',',array_fill(0,count($tables),'?')).')');$s->execute($tables);return(int)$s->fetchColumn()===count($tables);}catch(Throwable){return false;}}
