function knowledge_save_document(array$record):array{$existing=!empty($record['id'])?knowledge_find_document((int)$record['id']):null;if($existing&&($existing['status']??'')==='retired')throw new RuntimeException('Retired policy documents are immutable.');$entity=!empty($record['entity_id'])?(int)$record['entity_id']:null;if(!knowledge_visible_entity($entity))throw new RuntimeException('Policy document entity is outside the active scope.');knowledge_separated_users([(int)$record['owner_user_id'],(int)$record['reviewer_user_id'],(int)$record['approver_user_id']],'Policy ownership, review, and publication approval must remain separated.');if(trim((string)$record['title'])===''||trim((string)$record['purpose'])==='')throw new RuntimeException('Policy title and purpose are required.');$record['company_id']=knowledge_company_for_entity($entity);return knowledge_save_row('enterprise_policy_documents','enterprise_policy_documents','knowledge_demo_documents',$record,['document_number','title','document_type','entity_id','company_id','owner_user_id','reviewer_user_id','approver_user_id','purpose','status','current_version_id','created_by']);}
