function knowledge_submit_version(int$id,string$note):array{require_permission('knowledge_adoption.submit');$row=knowledge_find_version($id);if(!$row||$row['status']!=='draft')throw new RuntimeException('Policy version is not a draft awaiting submission.');if((int)$row['prepared_by']!==(int)current_user()['id'])throw new RuntimeException('Only the assigned preparer may submit this policy version.');if(trim($note)==='')throw new RuntimeException('Submission evidence is required.');$row['status']='submitted';$row['change_summary']=trim($row['change_summary']).' Submission: '.mb_substr(trim($note),0,2000);$row['content_hash']=knowledge_version_hash($row);$row['submitted_at']=date('Y-m-d H:i:s');return knowledge_save_version($row);}
