function knowledge_submit_attestation(int$assignmentId,string$acknowledgement,float$score,string$evidence):array{require_permission('knowledge_adoption.attest');$assignment=knowledge_find_assignment($assignmentId);if(!$assignment)throw new RuntimeException('Training assignment is outside the active scope.');if((int)$assignment['assigned_user_id']!==(int)current_user()['id'])throw new RuntimeException('Only the assigned learner may submit this attestation.');if(!in_array($assignment['status'],['assigned','in_progress','remediation'],true))throw new RuntimeException('Training assignment is not awaiting learner evidence.');if(trim($acknowledgement)===''||trim($evidence)==='')throw new RuntimeException('Acknowledgement and evidence are required.');$campaign=knowledge_find_campaign((int)$assignment['campaign_id']);$version=$campaign?knowledge_find_version((int)$campaign['version_id']):null;if(!$campaign||!$version||$version['status']!=='published')throw new RuntimeException('The assigned policy version is no longer published.');$key=hash('sha256',$assignmentId.'|'.$version['content_hash'].'|'.number_format($score,2,'.',''));foreach(knowledge_attestations($assignmentId)as$existing)if(hash_equals((string)$existing['idempotency_key'],$key))return$existing;$passed=$score>=(float)$campaign['required_score'];$number='ATT-'.date('Ymd').'-'.strtoupper(substr($key,0,6));$attestation=knowledge_save_attestation(['id'=>null,'assignment_id'=>$assignmentId,'version_id'=>$version['id'],'attestation_number'=>$number,'policy_hash'=>$version['content_hash'],'acknowledgement_text'=>mb_substr(trim($acknowledgement),0,5000),'quiz_score'=>max(0,min(100,$score)),'passed'=>$passed?1:0,'competency_status'=>$passed?'pending_validation':'remediation_required','status'=>'submitted','submitted_by'=>(int)current_user()['id'],'validator_user_id'=>$assignment['validator_user_id'],'evidence_note'=>mb_substr(trim($evidence),0,5000),'validation_note'=>'','idempotency_key'=>$key,'submitted_at'=>date('Y-m-d