function knowledge_campaign_metrics(int$campaignId):array{$assignments=knowledge_assignments($campaignId);$total=count($assignments);$completed=count(array_filter($assignments,static fn(array$row):bool=>$row['status']==='completed'));$waived=count(array_filter($assignments,static fn(array$row):bool=>$row['status']==='waived'));$overdue=count(array_filter($assignments,static fn(array$row):bool=>!in_array($row['status'],['completed','waived'],true)&&strtotime((string)$row['due_at'])<time()));$validated=0;$passed=0;foreach($assignments as$assignment)foreach(knowledge_attestations((int)$assignment['id'])as$attestation)if($attestation['status']==='validated'){$validated++;if($attestation['passed'])$passed++;break;}$adoption=$total>0?(($completed+$waived)/$total)*100:0;$passRate=$validated>0?($passed/$validated)*100:0;return['assigned'=>$total,'completed'=>$completed,'validated'=>$validated,'passed'=>$passed,'waived'=>$waived,'overdue'=>$overdue,'adoption_rate'=>round($adoption,2),'pass_rate'=>round($passRate,2)];}
