function knowledge_generate_manifest(int$versionId,string$note):array{require_permission('knowledge_adoption.export');$version=knowledge_find_version($versionId);$document=$version?knowledge_find_document((int)$version['document_id']):null;if(!$version||!$document||$version['status']!=='published')throw new RuntimeException('Evidence manifests require a published policy version.');$payload=['document'=>$document['document_number'],'version'=>$version['version_number'],'content_hash'=>$version['content_hash'],'links'=>knowledge_links($versionId),'impacts'=>knowledge_impacts($versionId),'campaigns'=>[]];foreach(knowledge_campaigns($versionId)as$campaign)$payload['campaigns'][]=['campaign'=>$campaign,'metrics'=>knowledge_campaign_metrics((int)$campaign['id']),'snapshots'=>knowledge_snapshots((int)$campaign['id'])];$json=json_encode($payload,JSON_UNESCAPED_SLASHES);$hash=hash('sha256',$json);foreach(knowledge_manifests($versionId)as$existing)if(hash_equals((string)$existing['manifest_hash'],$hash))return$existing;return knowledge_save_row('enterprise_policy_evidence_manifests','enterprise_policy_evidence_manifests','knowledge_demo_manifests',['id'=>null,'version_id'=>$versionId,'manifest_number'=>'EVD-'.date('Ymd').'-'.strtoupper(substr($hash,0,6)),'manifest_json'=>$json,'manifest_hash'=>$hash,'evidence_note'=>mb_substr(trim($note),0,5000),'generated_by'=>(int)current_user()['id'],'generated_at'=>date('Y-m-d H:i:s'),'locked_at'=>date('Y-m-d H:i:s')],['version_id','manifest_number','manifest_json','manifest_hash','evidence_note','generated_by','generated_at','locked_at']);}
function knowledge_metrics():array{$documents=knowledge_documents();$versions=knowledge_versions();$campaigns=knowledge_campaigns();$assignments=knowledge_assignments();$attestations=knowledge_attestations();$waivers=knowledge_waivers();$published=count(array_filter($versions,static fn(array$row):bool=>$row['status']==='published'));$overdue=count(array_filter($assignments,static fn(array$row):bool=>!in_array($row['status'],['completed','waived'],true)&&strtotime((string)$row['due_at'])<time()));$validated=count(array_filter($attestations,static fn(array$row):bool=>$row['status']==='validated'));$completed=count(array_filter($assignments,static fn(array$row):bool=>$row['status']==='completed'));$adoption=count($assignments)>0?(($completed+count(array_filter($assignments,static fn(array$row):bool=>$row['status']==='waived')))/count($assignments))*100:0;return['documents'=>count($documents),'published_versions'=>$published,'campaigns'=>count($campaigns),'assignments'=>count($assignments),'completed'=>$completed,'validated_attestations'=>$validated,'overdue'=>$overdue,'open_waivers'=>count(array_filter($waivers,static fn(array$row):bool=>in_array($row['status'],['submitted','reviewed'],true))),'adoption_rate'=>round($adoption,1)];}
function knowledge_export_csv():never{require_permission('knowledge_adoption.export');header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="knowledge-adoption-'.date('Ymd').'.csv"');$out=fopen('php://output','wb');fputcsv($out,['Assignment','Campaign','Policy','Version','Learner','Role','Status','Due','Completed','Renewal']);foreach(knowledge_assignments()as$assignment){$campaign=knowledge_find_campaign((int)$assignment['campaign_id']);$version=$campaign?knowledge_find_version((int)$campaign['version_id']):null;$document=$version?knowledge_find_document((int)$version['document_id']):null;fputcsv($out,[spreadsheet_safe($assignment['assignment_number']),spreadsheet_safe($campaign['campaign_name']??''),spreadsheet_safe($document['title']??''),spreadsheet_safe($version['version_number']??''),spreadsheet_safe(data_user_name((int)$assignment['assigned_user_id'])),spreadsheet_safe($assignment['assigned_role_code']),spreadsheet_safe($assignment['status']),spreadsheet_safe($assignment['due_at']),spreadsheet_safe($assignment['completed_at']??''),spreadsheet_safe($assignment['renewal_due_at']??'')]);}fclose($out);exit;}
