function knowledge_agent_escape(mixed$value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function knowledge_agent_extend_workspace(array$workspace):array{$metrics=knowledge_metrics();$risks=[];foreach(knowledge_assignments()as$assignment)if(!in_array($assignment['status'],['completed','waived'],true)&&strtotime((string)$assignment['due_at'])<time())$risks[]=$assignment;$rows=[];foreach(array_slice($risks,0,6)as$assignment){$campaign=knowledge_find_campaign((int)$assignment['campaign_id']);$rows[]='<li><strong>'.knowledge_agent_escape($assignment['assignment_number']).'</strong> · '.knowledge_agent_escape($campaign['campaign_name']??'Training').' · '.knowledge_agent_escape(data_user_name((int)$assignment['assigned_user_id'])).' · due '.knowledge_agent_escape(date_us($assignment['due_at'])).'</li>';}if(!$rows)$rows[]='<li>No visible training assignment is currently overdue.</li>';$prompt=['icon'=>'▣','title'=>'Policy, training and adoption','description'=>'Trace published policy versions into process impact, training, attestations, waivers and adoption.','prompt'=>'Which policy changes, training assignments, waivers or adoption gaps require attention, and what governed action should happen next?','keywords'=>['policy','sop','procedure','training','attestation','waiver','adoption','knowledge','work instruction','competency'],'response_title'=>'Knowledge & Adoption Agent','response_html'=>'<p><strong>'.$metrics['documents'].' documents · '.$metrics['published_versions'].' published versions · '.$metrics['assignments'].' assignments · '.$metrics['overdue'].' overdue · '.$metrics['adoption_rate'].'% adoption.</strong></p><ul>'.implode('',$rows).'</ul><p>Published hashes, Section 25 process versions, Section 29 initiatives, Section 26 work, and Section 27 deadlines remain authoritative. Recommendations require human review.</p><a class="agent-inline-link" href="'.knowledge_agent_escape(app_url('knowledge-adoption.php')).'">Open Knowledge & Adoption →</a>','evidence'=>[$metrics['published_versions'].' published versions',$metrics['validated_attestations'].' validated attestations',$metrics['open_waivers'].' open waivers',$metrics['overdue'].' overdue assignments'],'actions'=>[['type'=>'link','icon'=>'▣','label'=>'Open knowledge adoption','description'=>'Review governed policies and adoption evidence','href'=>app_url('knowledge-adoption.php')],['type'=>'prompt','icon'=>'!','label'=>'Explain adoption risk','description'=>'Trace policy requirements to overdue work and process impact','prompt'=>'Trace each adoption gap to its policy hash, process step, initiative, learner, validator, waiver status and next governed action.']],'confidence'=>'High','generated_at'=>date('Y-m-d H:i:s'),'human_review'=>'Required before policies, training, waivers, attestations, or evidence change','missing_data'=>[]];array_unshift($workspace['prompts'],$prompt);foreach(['documents','published_versions','campaigns','assignments','completed','validated_attestations','overdue','open_waivers','adoption_rate']as$key)$workspace['metrics']['knowledge_'.$key]=$metrics[$key];if(isset($workspace['briefing']['priorities']))foreach(array_slice($risks,0,3)as$assignment)$workspace['briefing']['priorities'][]=['severity'=>'high','category'=>'Knowledge adoption','title'=>$assignment['assignment_number'].' training overdue','description'=>'Required policy training and attestation remain incomplete.','meta'=>data_user_name((int)$assignment['assigned_user_id']).' · '.date_us($assignment['due_at']),'href'=>app_url('knowledge-adoption.php?tab=training'),'action_label'=>'Open training','agent_prompt'=>'Explain the policy, process, initiative, waiver and remediation evidence for '.$assignment['assignment_number'].'.'];return$workspace;}
function knowledge_render_styles():void{echo '<style>.know-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin:18px 0}.know-metrics article,.know-card{background:#fff;border:1px solid #dfe4ea;border-radius:16px;padding:16px;box-shadow:0 8px 28px rgba(17,24,39,.05)}.know-metrics span,.know-eyebrow{display:block;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#6b7280}.know-metrics strong{display:block;font-size:28px;margin:5px 0}.know-tabs{display:flex;gap:8px;overflow:auto;margin:0 0 18px}.know-tabs a{padding:10px 14px;border-radius:999px;border:1px solid #dfe4ea;background:#fff;white-space:nowrap}.know-tabs a.active{background:#111827;color:#fff}.know-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(320px,1fr);gap:18px}.know-list{display:grid;gap:12px}.know-row{display:grid;grid-template-columns:minmax(0,1.6fr) repeat(3,minmax(90px,.5fr));gap:12px;align-items:center;padding:14px;border:1px solid #e5e7eb;border-radius:14px}.know-row p,.know-row small{margin:3px 0;color:#6b7280}.know-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.know-form label{display:grid;gap:6px;font-weight:700}.know-form input,.know-form select,.know-form textarea{width:100%;padding:10px 12px;border:1px solid #cfd6df;border-radius:10px;background:#fff}.know-span-2{grid-column:span 2}.know-flow{display:grid;grid-template-columns:repeat(7,1fr);gap:8px;margin:16px 0}.know-flow span{padding:12px 8px;text-align:center;background:#f5f7fa;border-radius:12px;font-size:12px}.know-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:980px){.know-metrics{grid-template-columns:repeat(2,1fr)}.know-grid{grid-template-columns:1fr}.know-row{grid-template-columns:1fr 1fr}.know-form{grid-template-columns:1fr}.know-span-2{grid-column:auto}.know-flow{grid-template-columns:1fr 1fr}}</style>';}

